import { chromium, webkit } from 'playwright';
import fs from 'node:fs';
const base=process.env.KP_AUDIT_URL||'http://127.0.0.1:4173/';
const engines=[['chromium',chromium],['webkit',webkit]],clone=x=>JSON.parse(JSON.stringify(x));
const img=(label,w=700,h=1100)=>`data:image/svg+xml;base64,${Buffer.from(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${w} ${h}"><rect width="100%" height="100%" fill="#d6c09d"/><text x="30" y="80" font-size="42">${label}</text></svg>`).toString('base64')}`;
const initial={visited:['bernatek'],missionStatus:{bernatek:{done:true,updatedAt:'2026-08-12T10:00:00+02:00'}},missionEvidence:{bernatek:{id:'bernatek',title:'Foto verificada inicial',place:'Puente Bernatek',photo:img('verified',900,700),comment:'Inicial',by:'Ismael',verified:true,completedAt:'2026-08-12T10:00:00+02:00',updatedAt:'2026-08-12T10:00:00+02:00'}},albumPhotos:[],memories:[],expenses:[],config:{dailyTarget:21,fixedPaid:0},updatedAt:'2026-08-12T10:00:00+02:00'};
const report={target:base,generatedAt:new Date().toISOString(),engines:[],failures:[]};
for(const [name,engine] of engines){let browser;const checks=[],errors=[];const check=(n,ok,d='')=>{checks.push({name:n,ok:!!ok,detail:d});if(!ok)report.failures.push(`${name}: ${n}${d?` — ${d}`:''}`)};try{let cloud=clone(initial);browser=await engine.launch({headless:true});
 const make=async(player,state=cloud)=>{const ctx=await browser.newContext({viewport:{width:390,height:844},serviceWorkers:'block'});await ctx.addInitScript(({state,player})=>{localStorage.setItem('krakowPocketCoop',JSON.stringify(state));localStorage.setItem('krakowPlayer',player)},{state:clone(state),player});await ctx.route('https://ahzmwkztlakejmrvgcdm.supabase.co/rest/v1/rpc/**',async r=>{const u=r.request().url();if(u.includes('adventure_get'))return r.fulfill({status:200,contentType:'application/json',body:JSON.stringify(cloud)});if(u.includes('adventure_put')){try{const b=JSON.parse(r.request().postData()||'{}');if(b.p_state)cloud=clone(b.p_state)}catch{}return r.fulfill({status:200,contentType:'application/json',body:'{}'})}return r.fulfill({status:200,body:'{}'})});const page=await ctx.newPage();page.on('pageerror',e=>errors.push(String(e)));await page.goto(base,{waitUntil:'load'});await page.waitForFunction(()=>window.KP_ALBUM_NEXT?.version==='6.0'&&window.KP_STATE_BRIDGE?.version==='1.8',{timeout:15000});return{ctx,page}};
 const A=await make('Ismael');check('multi-photo runtime loaded',await A.page.evaluate(()=>window.KP_ALBUM_V5?.multiPhoto===true&&window.KP_STATE_BRIDGE?.sharedAlbumPhotos===true));
 await A.page.evaluate(({p1,p2})=>{const k='krakowPocketCoop',s=JSON.parse(localStorage.getItem(k)||'{}'),t1='2026-08-12T11:00:00+02:00',t2='2026-08-12T11:01:00+02:00';s.albumPhotos=[{id:'extra-a',missionId:'bernatek',title:'Vertical Ismael',place:'Puente Bernatek',photo:p1,comment:'Primera extra',by:'Ismael',completedAt:t1,updatedAt:t1,source:'album-extra'},{id:'extra-b',missionId:'bernatek',title:'Vertical Laura',place:'Puente Bernatek',photo:p2,comment:'Segunda extra',by:'Laura',completedAt:t2,updatedAt:t2,source:'album-extra'}];s.updatedAt=t2;localStorage.setItem(k,JSON.stringify(s));window.dispatchEvent(new CustomEvent('kp:album-photos-local'))},{p1:img('extra-ismael'),p2:img('extra-laura')});
 await A.page.waitForTimeout(500);let h=await A.page.evaluate(()=>window.KP_ALBUM_V5.html());check('same mission keeps three different photos',(h.match(/class="photo-card/g)||[]).length===3,`${(h.match(/class="photo-card/g)||[]).length}`);check('both extra titles render',h.includes('Vertical Ismael')&&h.includes('Vertical Laura'));check('vertical photos are uncropped',h.includes('data-kp-album-multi="1"')&&h.includes('object-fit:contain!important')&&h.includes('aspect-ratio:auto!important'));
 await A.page.evaluate(()=>{const el=document.getElementById('dailyTarget');if(el){el.value=String(Number(el.value||21)+1);el.dispatchEvent(new Event('change',{bubbles:true}))}});await A.page.waitForTimeout(1800);check('cloud receives albumPhotos',(cloud.albumPhotos||[]).filter(x=>!x.deletedAt).length===2,`${(cloud.albumPhotos||[]).length}`);
 const B=await make('Laura',cloud);await B.page.waitForTimeout(900);const secondHasBoth=await B.page.evaluate(()=>{const s=JSON.parse(localStorage.getItem('krakowPocketCoop')||'{}');return (s.albumPhotos||[]).filter(x=>!x.deletedAt).length===2});check('second iPhone receives both extras',secondHasBoth);
 await B.page.evaluate(({newPhoto})=>{const k='krakowPocketCoop',s=JSON.parse(localStorage.getItem(k)||'{}'),t='2026-08-12T12:00:00+02:00';s.missionEvidence.bernatek={...s.missionEvidence.bernatek,title:'Verificada nueva de Laura',photo:newPhoto,by:'Laura',updatedAt:t};s.updatedAt=t;localStorage.setItem(k,JSON.stringify(s));window.dispatchEvent(new CustomEvent('kp:mission-evidence-local',{detail:{id:'bernatek',entry:s.missionEvidence.bernatek}}));const el=document.getElementById('dailyTarget');if(el){el.value=String(Number(el.value||21)+1);el.dispatchEvent(new Event('change',{bubbles:true}))}},{newPhoto:img('verified-laura',900,700)});await B.page.waitForTimeout(2200);const archived=await B.page.evaluate(()=>{const s=JSON.parse(localStorage.getItem('krakowPocketCoop')||'{}');return (s.albumPhotos||[]).some(x=>x.source==='mission-history'&&x.missionId==='bernatek')});check('superseded verified photo archived',archived);
 await A.page.waitForTimeout(5500);await A.page.reload({waitUntil:'load'});await A.page.waitForFunction(()=>window.KP_ALBUM_NEXT?.version==='6.0',{timeout:15000});await A.page.waitForTimeout(1200);const stateA=await A.page.evaluate(()=>JSON.parse(localStorage.getItem('krakowPocketCoop')||'{}'));check('new verified photo survives reload',stateA.missionEvidence?.bernatek?.title==='Verificada nueva de Laura',stateA.missionEvidence?.bernatek?.title||'missing');check('extra photos survive reload',stateA.albumPhotos?.filter(x=>!x.deletedAt).length>=3,`${stateA.albumPhotos?.length||0}`);h=await A.page.evaluate(()=>window.KP_ALBUM_V5.html());check('album after reload contains old and new memories',h.includes('Verificada nueva de Laura')&&h.includes('Foto verificada inicial')&&h.includes('Vertical Ismael')&&h.includes('Vertical Laura'));
 await A.page.evaluate(()=>{const k='krakowPocketCoop',s=JSON.parse(localStorage.getItem(k)||'{}'),p=s.albumPhotos.find(x=>x.id==='extra-a'),t='2026-08-12T13:00:00+02:00';p.deletedAt=t;p.updatedAt=t;s.updatedAt=t;localStorage.setItem(k,JSON.stringify(s));window.dispatchEvent(new CustomEvent('kp:album-photos-local'));const el=document.getElementById('dailyTarget');if(el){el.value=String(Number(el.value||21)+1);el.dispatchEvent(new Event('change',{bubbles:true}))}});await A.page.waitForTimeout(1800);h=await A.page.evaluate(()=>window.KP_ALBUM_V5.html());check('deleted extra is not rendered',!h.includes('Vertical Ismael')&&h.includes('Vertical Laura'));
 await B.ctx.close();await A.ctx.close();check('no runtime errors',errors.length===0,errors.join(' | ').slice(0,800));
 }catch(e){check('audit completed',false,String(e?.stack||e).slice(0,1400))}finally{try{await browser?.close()}catch{}report.engines.push({engine:name,checks,errors})}}
fs.writeFileSync('/tmp/album-multi-r1.json',JSON.stringify(report,null,2));console.log(JSON.stringify(report,null,2));if(report.failures.length)process.exitCode=1;
